INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '2c5a98b1-90c4-4f88-a2b3-1c4f9b012a10'::uuid, 'landing-page-my-pham-tiktok-shop', 'Template Landing Page Mỹ Phẩm Chuẩn TikTok Shop', 'Mẫu landing page bán mỹ phẩm dưỡng da tối ưu mobile 375px, gắn giỏ hàng TikTok Shop & Shopee.', 'Gói template Next.js + HTML/CSS do nhóm tự thiết kế dành riêng cho shop mỹ phẩm 1–3 nhân sự. Tập trung trình bày bảng thành phần dịu nhẹ, chứng nhận công bố sản phẩm, CTA chốt đơn nhanh qua TikTok Shop/Shopee và tuân thủ chính sách quảng cáo không cam kết trị liệu.', 'template', 'Mỹ phẩm', 490000, '/demos/landing-page-my-pham-tiktok-shop/index.html', '/images/cat-template.webp', 'original', 'Sản phẩm gốc do nhóm nghiên cứu tự thiết kế 100%, cấp quyền sử dụng thương mại cho 1 shop.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Shopee","Facebook"],"deliverables":["Source code template responsive 375px - 1440px","Bảng nội dung chuẩn chính sách mỹ phẩm không trị liệu","Khối hiển thị giấy công bố & hướng dẫn triển khai trong 30 phút"],"tech_stack":["HTML5","CSS3","Next.js"],"setup_time_minutes":30,"guide_summary":"Thay logo, bảng thành phần, giá bán và link sản phẩm TikTok Shop để chạy ngay.","preview_highlights":["Bố cục Hero chuẩn mobile 375px hiển thị rõ số công bố CBMP và bảng thành phần dịu nhẹ.","2 nút CTA chốt đơn tức thì chuyển hướng sang giỏ hàng TikTok Shop và Shopee Mall.","Khối trình bày kết cấu sản phẩm & hướng dẫn sử dụng an toàn, tránh từ ngữ cam kết trị liệu."],"case_studies":[{"shop_name":"Tiệm Dưỡng Da An Nhiên","shop_type":"Shop mỹ phẩm 2 nhân sự (TP.HCM)","rating":5,"quote":"Trước đây gắn link Bio bị loãng khách, từ ngày đưa khách qua landing page này để xem rõ số công bố và thành phần, tỷ lệ bấm sang giỏ TikTok Shop tăng rõ mà không bị quét từ cấm.","outcome":"Tăng 32% lượt bấm sang giỏ hàng TikTok Shop sau 2 tuần"},{"shop_name":"Mộc Skincare Đà Nẵng","shop_type":"Cửa hàng chăm sóc da cá nhân (1 người)","rating":4.9,"quote":"Mình không rành code nhưng chỉ mất khoảng 25 phút thay ảnh lọ serum và giá bán theo hướng dẫn là chạy được ngay trên điện thoại.","outcome":"Tự xuất bản trang bán hàng trong 25 phút, giảm câu hỏi lặp lại về thành phần"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug,
  name = EXCLUDED.name,
  short_description = EXCLUDED.short_description,
  description = EXCLUDED.description,
