INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '7a9c11d2-54e3-4c99-8b10-0f2d3e4a5b6c'::uuid, 'prompt-pack-mo-ta-my-pham', 'Prompt Pack Mô Tả & Kịch Bản Video Mỹ Phẩm', '60 prompt AI viết mô tả sản phẩm dưỡng da, kịch bản TikTok 30s không vi phạm từ cấm.', 'Bộ 60 prompt tối ưu cho chủ shop mỹ phẩm viết mô tả chuẩn SEO Shopee/TikTok Shop, trả lời bình luận khách hỏi về loại da và dựng kịch bản video ngắn tránh các từ ngữ cam kết điều trị y khoa.', 'prompt_pack', 'Mỹ phẩm', 290000, NULL, '/images/cat-prompt.webp', 'original', 'Bộ prompt biên soạn gốc bởi nhóm nội dung, dùng không giới hạn cho các kênh của 1 shop.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Shopee","Facebook"],"deliverables":["60 prompt phân loại theo tình huống bán hàng mỹ phẩm","Checklist từ khóa bị hạn chế trên sàn TMĐT","Bộ khung kịch bản video ngắn 30 giây quay bằng điện thoại"],"tech_stack":["Notion","Markdown","PDF"],"setup_time_minutes":15,"guide_summary":"Điền tên sản phẩm, thành phần chính và tệp da khách hàng vào khung mẫu để tạo mô tả chuẩn.","preview_highlights":["60 prompt chia theo 4 nhóm: mô tả Shopee/TikTok Shop, kịch bản video 30s, trả lời comment loại da.","Đi kèm checklist từ khóa nhạy cảm cần tránh trên sàn TMĐT ngành mỹ phẩm.","Khung điền biến số 3 bước, sao chép dùng ngay trên Notion hoặc PDF."],"case_studies":[{"shop_name":"Lành Beauty Corner","shop_type":"Shop mỹ phẩm thiên nhiên (2 người, Hà Nội)","rating":5,"quote":"Nhờ checklist từ cấm đi kèm mà đội mình viết lại toàn bộ mô tả 18 mã kem chống nắng và sữa rửa mặt sạch sẽ, không còn bị sàn cảnh báo nội dung.","outcome":"Rút ngắn thời gian viết mô tả mỗi sản phẩm mới từ 45 phút xuống còn 10 phút"},{"shop_name":"Bông Skincare Shop","shop_type":"Chủ shop bán lẻ Shopee & TikTok (1 người)","rating":4.8,"quote":"Bộ kịch bản video 30 giây quay bằng điện thoại rất vừa sức người mới, đọc theo khung có sẵn nên quay 1 buổi được cả tuần.","outcome":"Hoàn thành đều 5 clip giới thiệu sản phẩm/tuần không cần thuê viết kịch bản"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug,
  name = EXCLUDED.name,
  short_description = EXCLUDED.short_description,
  description = EXCLUDED.description,
