INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'f6a7b8c9-1012-4112-8112-6c7d8e9f0a12'::uuid, 'workflow-nhac-mua-lai-my-pham-zalo', 'Workflow Nhắc Lịch Mua Lại & CSKH Mỹ Phẩm Tự Động', 'Luồng n8n/Make nhắc chu kỳ hết sản phẩm sau 30–45 ngày qua Google Sheets, Telegram & mẫu Zalo.', 'Giải pháp tự động hóa giữ chân khách hàng dành riêng cho shop mỹ phẩm nhỏ không dùng CRM đắt tiền. Khi ghi nhận đơn dưỡng da vào Google Sheets, hệ thống tự tính ngày dự kiến dùng hết (30–45 ngày) và gửi thông báo nhắc nhân viên chăm sóc khách quay lại mua tiếp.', 'workflow', 'Mỹ phẩm', 640000, NULL, '/images/cat-workflow.webp', 'adapted', 'Chuyển thể từ cấu trúc luồng nhắc lịch mở trên n8n, Việt hóa và thiết kế lại bảng theo dõi chu kỳ dùng hết sản phẩm mỹ phẩm cho shop nhỏ.', '{"target_shop_size":"1-3 người","platforms":["Zalo","Google Sheets","Telegram"],"deliverables":["File JSON workflow n8n/Make nhập 1 chạm","Google Sheets mẫu quản lý chu kỳ mua lại 30–45 ngày","10 mẫu tin nhắn hỏi thăm dịu nhẹ đúng chính sách Zalo"],"tech_stack":["n8n / Make","Google Sheets","Telegram Bot"],"setup_time_minutes":40,"guide_summary":"Kết nối Google Sheets đơn hàng với bot Telegram để nhận danh sách khách cần nhắc chăm sóc mỗi sáng.","preview_highlights":["File JSON n8n/Make nhập 1 chạm, tự động tính chu kỳ dùng hết sản phẩm 30–45 ngày.","Đồng bộ từ Google Sheets đơn hàng sang thông báo Telegram nhắc lịch mỗi sáng.","Kèm 10 mẫu tin nhắn chăm sóc dịu nhẹ qua Zalo giúp giữ chân khách cũ."],"case_studies":[{"shop_name":"Cỏ Mềm Mini Store","shop_type":"Shop dưỡng da gia đình (3 nhân sự, Cần Thơ)","rating":5,"quote":"Shop nhỏ chưa đủ kinh phí mua CRM đắt tiền, dùng Google Sheets nối Telegram này mỗi sáng tự báo danh sách 5–7 khách sắp hết toner để nhắn hỏi thăm rất gọn.","outcome":"Tiết kiệm 45 phút dò sổ tay mỗi ngày và giữ nhịp chăm sóc khách quay lại"},{"shop_name":"Hương Thảo Cosmetics","shop_type":"Cửa hàng mỹ phẩm online (2 nhân sự, Bình Dương)","rating":4.9,"quote":"10 mẫu tin nhắn Zalo viết tự nhiên, không bị cảm giác spam quảng cáo nên khách cũ phản hồi lại rất thoải mái.","outcome":"28% khách được nhắc chu kỳ 35 ngày quay lại đặt tiếp chai thứ hai"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
