INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '3d6b22e3-11a4-4d88-9c21-2e3f4a5b6c7d'::uuid, 'template-lookbook-thoi-trang-local', 'Template Lookbook Thời Trang Shop Nhỏ', 'Giao diện trưng bày bộ sưu tập quần áo kèm bảng size trực quan và nút đặt hàng nhanh.', 'Thiết kế dành cho shop thời trang nữ/unisex bán trên Instagram, Facebook và Shopee. Hỗ trợ hiển thị ảnh lookbook theo mùa, bảng quy đổi size rõ ràng trên điện thoại và form giữ đơn nhanh cho khách xem live.', 'template', 'Thời trang', 590000, '/demos/template-lookbook-thoi-trang-local/index.html', '/images/cat-template.webp', 'original', 'Mã nguồn thiết kế gốc bởi nhóm tác giả, hỗ trợ tùy biến màu sắc theo nhận diện shop.', '{"target_shop_size":"1-5 người","platforms":["Instagram","Facebook","Shopee"],"deliverables":["Template Lookbook + Bảng size responsive theo chiều cao cân nặng","Form giữ đơn nhanh gắn link Shopee/Instagram","Bộ banner kích thước chuẩn mạng xã hội"],"tech_stack":["HTML5","CSS3","TypeScript"],"setup_time_minutes":40,"guide_summary":"Cập nhật bộ ảnh lookbook theo mùa và thông số size S/M/L để khách tự đối chiếu trước khi đặt.","preview_highlights":["Trưng bày bộ sưu tập theo từng set phối sẵn với ảnh dọc tỷ lệ chuẩn lookbook.","Tích hợp công cụ gợi ý size S/M/L/XL theo chiều cao & cân nặng ngay trên trang.","Form giữ đơn nhanh nối trực tiếp sang Shopee hoặc tin nhắn Instagram."],"case_studies":[{"shop_name":"Studio Bắc Nam","shop_type":"Shop thời trang nữ local (3 người, TP.HCM)","rating":5,"quote":"Khách Instagram hay hỏi lặp lại cao 1m60 nặng 52kg mặc size gì. Từ khi gắn trang lookbook có bảng tính size tự động, tin nhắn hỏi size giảm hẳn mà đơn đổi trả cũng ít đi.","outcome":"Giảm 40% tỷ lệ đổi size nhầm và rút ngắn thời gian chốt inbox"},{"shop_name":"Tiệm Vải Cô Ba","shop_type":"Shop đồ linen thủ công (2 người, Hội An)","rating":4.8,"quote":"Giao diện sáng, nhìn sang như tạp chí nhưng tải rất nhẹ trên điện thoại, hợp với khách xem link từ story Facebook.","outcome":"Tăng số đơn đặt trọn bộ áo + quần phối sẵn thêm 22%"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
