INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'a1b2c3d4-1007-4107-8107-1c4f9b012a07'::uuid, 'template-landing-livestream-thoi-trang', 'Template Landing Page Flash Sale & Livestream Thời Trang', 'Trang gom đơn nhanh theo mã sản phẩm khi livestream TikTok/Facebook, tối ưu chọn màu & size trên di động.', 'Mẫu landing page chuyên dụng cho các shop thời trang bán qua phiên livestream hoặc xả kho cuối tuần. Hiển thị mã số sản phẩm theo thứ tự live, bộ đếm giữ giá ưu đãi, chọn nhanh biến thể màu/size và chuyển tiếp về giỏ hàng sàn hoặc inbox.', 'template', 'Thời trang', 550000, '/demos/template-landing-livestream-thoi-trang/index.html', '/images/cat-template.webp', 'adapted', 'Chuyển thể từ khung layout bán hàng mở nội bộ, tối ưu lại luồng gom đơn theo mã live cho shop thời trang Việt Nam.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Facebook","Shopee"],"deliverables":["Trang danh sách mã live tìm kiếm tức thì theo mã #A01, #A02","Khối bộ đếm khung giờ Flash Sale & bảng chọn size/màu","Tài liệu hướng dẫn gắn link giỏ hàng trước giờ lên live"],"tech_stack":["HTML5","CSS3","Next.js"],"setup_time_minutes":30,"guide_summary":"Nhập danh sách mã hàng live vào file cấu hình JSON để ghim link trang gom đơn lên bình luận.","preview_highlights":["Thanh tìm kiếm tức thì theo mã đọc trên livestream (#A01, #A02, #A03).","Bộ đếm khung giờ Flash Sale và nút giữ size/màu trực quan trên di động.","Cập nhật danh sách mã hàng live dễ dàng qua file cấu hình JSON trước giờ lên sóng."],"case_studies":[{"shop_name":"Xưởng Gấu Local Brand","shop_type":"Shop bán livestream TikTok 2 người (Hà Nội)","rating":5,"quote":"Khi live có lúc vài trăm người xem, đọc bình luận không xuể. Ghim link trang mã live lên để khách tự gõ #A05 chọn size giúp đỡ sót đơn hẳn.","outcome":"Giảm tình trạng sót bình luận giữ đơn trong khung giờ cao điểm xuống dưới 5%"},{"shop_name":"Kho Sỉ Lẻ Mint","shop_type":"Shop xả kho thời trang cuối tuần (3 người, TP.HCM)","rating":4.9,"quote":"Trước mỗi phiên live mình chỉ mất 20 phút nhập lại mã hàng và giá ưu đãi vào danh sách là dùng lại được cho cả tháng.","outcome":"Chuẩn bị xong trang gom đơn chỉ trong 20 phút trước mỗi phiên live"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
