INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'd4e5f6a7-1010-4110-8110-4a5b6c7d8e10'::uuid, 'prompt-pack-phoi-do-livestream-thoi-trang', 'Prompt Pack Phối Đồ, Tư Vấn Size & Kịch Bản Live Thời Trang', '55 prompt gợi ý mix-match theo dáng người, tư vấn size giảm hoàn hàng và kịch bản dẫn livestream 60s.', 'Bộ prompt dành cho chủ shop quần áo bận rộn bán trên Instagram, Facebook, TikTok Shop và Shopee. Hỗ trợ viết caption lookbook tự nhiên, trả lời nhanh câu hỏi chọn size theo số đo để hạn chế đổi trả, gợi ý phối thêm phụ kiện tăng giá trị đơn và soạn sườn nói chuyện khi live.', 'prompt_pack', 'Thời trang', 320000, NULL, '/images/cat-prompt.webp', 'original', 'Biên soạn gốc bởi nhóm nội dung, cấp quyền sử dụng lâu dài cho mọi kênh bán hàng của 1 thương hiệu thời trang.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Instagram","Facebook","Shopee"],"deliverables":["55 prompt chia 4 nhóm: Caption Lookbook, Tư vấn size, Mix-match, Kịch bản Live","Bảng mẫu phản hồi khách hỏi chất vải và chính sách đổi size","Checklist chuẩn bị nội dung trước phiên livestream 30 phút"],"tech_stack":["Notion","Markdown","PDF"],"setup_time_minutes":15,"guide_summary":"Chọn nhóm prompt tương ứng (đăng bài mới hoặc rep inbox chọn size) rồi điền thông số chất liệu, form dáng.","preview_highlights":["55 prompt chia 4 nhóm: Caption Lookbook, Tư vấn size theo số đo, Gợi ý mix-match, Kịch bản Live 60s.","Bảng mẫu xử lý câu hỏi chất liệu vải, độ co giãn và chính sách đổi trả.","Checklist chuẩn bị kịch bản nói chuyện trước khi bật livestream 30 phút."],"case_studies":[{"shop_name":"Nắng Boutique","shop_type":"Shop quần áo nữ Instagram (1 người, Hải Phòng)","rating":4.9,"quote":"Mình vừa nhập hàng vừa tự rep tin nhắn nên hay bí từ khi viết caption buổi tối. Bộ prompt gợi ý phối đồ giúp bài đăng tự nhiên hơn hẳn.","outcome":"Tiết kiệm khoảng 5 giờ mỗi tuần cho việc viết caption và trả lời inbox"},{"shop_name":"Tủ Đồ Minimal","shop_type":"Shop unisex nhỏ (2 nhân sự, Đà Nẵng)","rating":5,"quote":"Nhóm prompt tư vấn size theo dáng người giúp bạn nhân viên mới trả lời khách tự tin và nhất quán như chủ shop.","outcome":"Nhân viên mới làm quen kịch bản tư vấn chỉ sau 1 ngày"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
