INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '4e7c33f4-22b5-4e99-ad32-3f4a5b6c7d8e'::uuid, 'template-menu-dat-mon-fnb-mini', 'Template Menu & Đặt Món Nhanh Quán F&B Nhỏ', 'Trang menu điện tử quét QR, chọn topping và gửi đơn chốt nhanh qua Zalo/Messenger.', 'Giải pháp gọn nhẹ cho quán đồ uống, tiệm bánh online hoặc bếp nhà làm quy mô 1–3 người. Khách hàng chọn món, ghi chú độ ngọt/đá trên điện thoại và gửi tóm tắt đơn thẳng về kênh chat của chủ quán.', 'template', 'F&B', 450000, '/demos/template-menu-dat-mon-fnb-mini/index.html', '/images/cat-template.webp', 'adapted', 'Chuyển thể và tối ưu lại từ cấu trúc giao diện mở nội bộ, cấp phép sử dụng cho 1 chi nhánh.', '{"target_shop_size":"1-3 người","platforms":["Zalo","Facebook","QR tại quán"],"deliverables":["Trang Menu tương tác + giỏ hàng mini chọn topping, độ ngọt/đá","Nút xuất tóm tắt đơn 1 chạm gửi qua Zalo/Messenger","File QR code mẫu đặt tại quầy & bàn uống nước"],"tech_stack":["HTML5","CSS3","JavaScript"],"setup_time_minutes":25,"guide_summary":"Điền danh sách món, giá topping và link Zalo OA/số Zalo quán rồi in mã QR đặt tại bàn.","preview_highlights":["Menu điện tử quét mã QR hiển thị rõ phân nhóm đồ uống, món ăn kèm giá và ảnh.","Giỏ chọn món mini hỗ trợ chọn size, topping, mức đường/đá trực tiếp trên điện thoại.","Xuất tóm tắt đơn thành đoạn văn bản gọn gàng gửi 1 chạm qua Zalo/Messenger."],"case_studies":[{"shop_name":"Trà Sữa Nhà Gạo","shop_type":"Quán đồ uống take-away (2 người, Thủ Đức)","rating":5,"quote":"Khách đặt qua Zalo trước hay nhắn lắt nhắt từng dòng dễ thiếu topping. Giờ gửi link menu để khách bấm chọn xong copy gửi qua một tin nhắn rất rõ ràng.","outcome":"Hạn chế nhầm lẫn độ ngọt/đá và topping trong giờ cao điểm trưa"},{"shop_name":"Bếp Cà Phê Sân Vườn","shop_type":"Quán cà phê nhỏ 12 bàn (3 nhân sự, Biên Hòa)","rating":4.8,"quote":"In mã QR đặt trên bàn bằng mẫu kèm theo, khách tự xem menu và gọi thêm món không cần chờ in lại thực đơn giấy mỗi khi đổi món.","outcome":"Không tốn chi phí in lại menu giấy khi cập nhật món theo mùa"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug,
  name = EXCLUDED.name,
