INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'b2c3d4e5-1008-4108-8108-2e3f4a5b6c08'::uuid, 'template-dat-combo-tiem-banh-fnb', 'Template Website Đặt Combo Tiệm Bánh & Quà Tặng F&B', 'Mẫu web đặt hộp bánh, set trà chiều có chọn khung giờ giao hẹn trước và nhập lời chúc trên thiệp.', 'Thiết kế tối ưu cho tiệm bánh thủ công, bếp đồ ăn vặt và cửa hàng set quà F&B bán theo đơn đặt trước (pre-order). Cho phép khách chọn combo vị bánh, khung giờ nhận trong ngày, nhập nội dung thiệp tặng và gửi xác nhận về Zalo/Messenger của tiệm.', 'template', 'F&B', 520000, '/demos/template-dat-combo-tiem-banh-fnb/index.html', '/images/cat-template.webp', 'licensed', 'Sử dụng bộ UI kit và biểu tượng ẩm thực theo giấy phép thương mại mở rộng hợp lệ, luồng đặt combo và nội dung tiếng Việt do nhóm biên tập độc lập.', '{"target_shop_size":"1-4 người","platforms":["Zalo","Facebook","Instagram"],"deliverables":["Template trang đặt combo theo khung giờ giao nhận","Form ghi chú thiệp chúc & dị ứng nguyên liệu","Bộ ảnh khung trình bày hộp quà chuẩn tỷ lệ 4:3"],"tech_stack":["HTML5","CSS3","TypeScript"],"setup_time_minutes":35,"guide_summary":"Cài đặt khung giờ bếp giao hàng trong ngày và danh sách combo để khách đặt trước không bị trùng lịch.","preview_highlights":["Luồng đặt trước (Pre-order) cho hộp bánh, set trà chiều có chọn khung giờ giao nhận.","Ô ghi chú lời chúc trên thiệp tặng và cảnh báo dị ứng thành phần (hạt, sữa).","Tóm tắt combo và khung giờ xác nhận gửi thẳng về Zalo/Messenger của tiệm."],"case_studies":[{"shop_name":"Bếp Bánh Mì Hoa Cúc","shop_type":"Tiệm bánh online làm tại nhà (2 người, Hà Nội)","rating":5,"quote":"Dịp lễ 20/10 và 8/3 khách đặt hộp quà rất dồn. Có khung chọn giờ giao nhận theo ca sáng/chiều giúp bếp sắp lịch nướng bánh không bị vỡ đơn.","outcome":"Quản lý trơn tru hơn 45 hộp bánh đặt trước dịp lễ không trễ giờ giao"},{"shop_name":"Tiệm Trà Chiều Mây","shop_type":"Cửa hàng set bánh & trà (3 nhân sự, Đà Lạt)","rating":4.9,"quote":"Mục ghi sẵn lời chúc thiệp tặng trên form giúp tiệm đỡ phải hỏi lại từng khách trên Messenger, ghi chú nào cũng lưu rõ ràng.","outcome":"Rút ngắn thời gian xác nhận mỗi đơn quà tặng từ 8 phút xuống 2 phút"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
