INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'e5f6a7b8-1011-4111-8111-5b6c7d8e9f11'::uuid, 'prompt-pack-mo-ta-mon-fnb-review', 'Prompt Pack Mô Tả Món Ăn & Kịch Bản Video Review F&B', '50 prompt viết thực đơn hấp dẫn cho ShopeeFood/Zalo, kịch bản clip pha chế 20s và mẫu trả lời đánh giá.', 'Giúp chủ quán ăn, tiệm trà sữa, tiệm bánh online tự viết mô tả món ăn gợi vị giác chuẩn app giao đồ ăn, dựng video ngắn quay cảnh làm món tại quầy và phản hồi đánh giá 1–5 sao tinh tế để giữ điểm uy tín quán.', 'prompt_pack', 'F&B', 260000, NULL, '/images/cat-prompt.webp', 'original', 'Bộ prompt biên soạn gốc bởi nhóm nội dung, dùng không giới hạn cho các kênh bán hàng của 1 quán F&B.', '{"target_shop_size":"1-3 người","platforms":["ShopeeFood","TikTok","Zalo","Facebook"],"deliverables":["50 prompt viết mô tả món & combo tăng giá trị giỏ hàng","15 kịch bản video quay món/pha chế 20–30 giây","20 mẫu phản hồi đánh giá khách hàng (khen và góp ý)"],"tech_stack":["Notion","Markdown","PDF"],"setup_time_minutes":10,"guide_summary":"Nhập tên món, nguyên liệu đặc trưng và mức giá combo để tạo ngay mô tả chuẩn app giao đồ ăn.","preview_highlights":["50 prompt viết mô tả món ăn gợi vị giác chuẩn ShopeeFood, GrabFood và Zalo.","15 kịch bản video quay cảnh pha chế/ra món 20–30 giây tại quầy bằng điện thoại.","20 mẫu phản hồi đánh giá 1–5 sao lịch sự giúp giữ điểm uy tín quán."],"case_studies":[{"shop_name":"Bún Trộn Cô Tư","shop_type":"Quán ăn gia đình bán app giao đồ ăn (3 người, Q.3 TP.HCM)","rating":4.9,"quote":"Viết lại tên món và mô tả combo trưa trên ShopeeFood theo prompt thấy hấp dẫn và rõ ràng hơn, khách hay đặt thêm phần topping kèm theo.","outcome":"Giá trị trung bình mỗi đơn app giao hàng tăng nhẹ nhờ mô tả combo rõ ràng"},{"shop_name":"Tiệm Trà Trái Cây Vườn Xanh","shop_type":"Quán đồ uống online (2 người, Huế)","rating":5,"quote":"Mình hay lúng túng khi khách góp ý 3 sao về thời gian giao hàng. Bộ mẫu trả lời đánh giá giúp phản hồi khéo léo, giữ thiện cảm với khách.","outcome":"Phản hồi 100% đánh giá mới trong ngày với giọng văn đồng nhất"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
