INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'c3d4e5f6-1009-4109-8109-3f4a5b6c7d09'::uuid, 'template-bio-link-cua-hang-mini-da-kenh', 'Template Trang Bio Link & Cửa Hàng Mini Đa Kênh', 'Trang tổng hợp link Shopee, TikTok Shop, Zalo OA và 8–12 sản phẩm chủ lực gắn trên bio mạng xã hội.', 'Phù hợp cho mọi chủ shop nhỏ bán cùng lúc nhiều kênh và cần một trang đích duy nhất gắn trên tiểu sử TikTok, Instagram, Facebook. Tải trang siêu nhẹ trên 4G, hiển thị mã giảm giá theo sàn và dẫn khách sang đúng kênh đặt mua quen thuộc.', 'template', 'Đa ngành', 390000, '/demos/template-bio-link-cua-hang-mini-da-kenh/index.html', '/images/cat-template.webp', 'licensed', 'Sử dụng bộ icon và font cấp phép thương mại hợp lệ; cấu trúc trang Bio Link & cửa hàng mini được nhóm đóng gói chuẩn hóa cho shop Việt Nam.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Shopee","Zalo","Instagram"],"deliverables":["Trang Bio Link + Danh mục 12 sản phẩm chủ lực tối ưu di động","Nút điều hướng đa sàn kèm sao chép nhanh voucher","Hướng dẫn xuất bản miễn phí lên Vercel/Netlify trong 20 phút"],"tech_stack":["HTML5","CSS3","JavaScript"],"setup_time_minutes":20,"guide_summary":"Gắn URL gian hàng Shopee, TikTok Shop và Zalo OA vào file cấu hình rồi gắn link trang lên bio.","preview_highlights":["Trang đích duy nhất gom link Shopee, TikTok Shop, Zalo OA và 8–12 sản phẩm chủ lực.","Hộp sao chép nhanh mã giảm giá từng sàn ngay trên giao diện mobile.","Tải trang siêu nhẹ trên mạng 4G, xuất bản miễn phí lên Vercel/Netlify trong 20 phút."],"case_studies":[{"shop_name":"Kho Gia Dụng Tiện Lợi","shop_type":"Shop bán đa kênh (2 người, Bắc Ninh)","rating":5,"quote":"Shop mình bán cả Shopee, TikTok lẫn Zalo nhưng mỗi nền tảng chỉ gắn được 1 link tiểu sử. Trang Bio mini này giúp khách quen sàn nào bấm sang sàn đó rất tiện.","outcome":"Gom toàn bộ 10 sản phẩm bán chạy vào 1 link bio tải dưới 1 giây"},{"shop_name":"Tạp Hóa Nhỏ Nhà Bơ","shop_type":"Cửa hàng đồ mẹ & bé, gia dụng (1 người, TP.HCM)","rating":4.8,"quote":"Nút sao chép voucher đặt ngay trên đầu trang nên khách từ TikTok bấm qua Shopee lấy mã rất nhanh.","outcome":"Thiết lập xong toàn bộ link gian hàng và voucher trong 20 phút"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
