INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '5f8d44a5-33c6-4fa0-be43-4a5b6c7d8e9f'::uuid, 'prompt-pack-chot-don-da-kenh', 'Prompt Pack Chăm Sóc Khách & Chốt Đơn Đa Kênh', '50 kịch bản phản hồi inbox, xử lý từ chối giá và nhắc đơn hoàn thành cho chủ shop bận rộn.', 'Phù hợp cho mọi ngành hàng bán lẻ trên Shopee, TikTok Shop và Facebook. Giúp chủ shop soạn nhanh mẫu trả lời đồng nhất về phí ship, đổi trả, giữ chân khách cũ mà vẫn giữ giọng văn thân thiện tự nhiên.', 'prompt_pack', 'Đa ngành', 250000, NULL, '/images/cat-prompt.webp', 'original', 'Tài liệu biên soạn gốc bởi nhóm đề tài, kèm file Notion và PDF tải về.', '{"target_shop_size":"1-3 người","platforms":["Shopee","TikTok Shop","Facebook","Zalo"],"deliverables":["50 mẫu prompt trả lời khách theo ngữ cảnh (hỏi giá, phí ship, đổi trả)","Bảng mẫu tin nhắn nhanh (Quick Reply) cho giờ cao điểm","Kịch bản nhắn tin xin đánh giá tự nhiên sau giao hàng"],"tech_stack":["Notion","Markdown","PDF"],"setup_time_minutes":10,"guide_summary":"Sao chép các mẫu Quick Reply vào bộ trả lời nhanh của Shopee/Facebook/Zalo để dùng ngay.","preview_highlights":["50 mẫu prompt trả lời khách theo tình huống thực tế: hỏi giá, phí ship, kiểm hàng, đổi trả.","Bộ mẫu Quick Reply rút gọn để dán thẳng vào tin nhắn nhanh Shopee/Facebook/Zalo.","Kịch bản nhắn tin xin đánh giá 5 sao tự nhiên sau khi giao hàng thành công."],"case_studies":[{"shop_name":"Phụ Kiện Điện Thoại An Phát","shop_type":"Shop bán phụ kiện đa sàn (2 người, TP.HCM)","rating":4.9,"quote":"Mình copy bộ Quick Reply vào mục trả lời nhanh của Shopee và Fanpage, giờ cao điểm tối một mình vẫn xử lý kịp vài chục tin nhắn.","outcome":"Giảm thời gian phản hồi trung bình xuống dưới 3 phút trong khung giờ tối"},{"shop_name":"Góc Đồ Bếp Xinh","shop_type":"Shop đồ gia dụng nhỏ (1 người, Hải Phòng)","rating":4.8,"quote":"Mấy mẫu xử lý khi khách chê phí ship cao viết rất khéo, gợi ý khách ghép thêm món nhỏ để được miễn phí vận chuyển hiệu quả hơn hẳn.","outcome":"Cải thiện tỷ lệ khách đồng ý ghép đơn đủ điều kiện freeship"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
