INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '6a9e55b6-44d7-40b1-cf54-5b6c7d8e9f01'::uuid, 'workflow-dong-bo-don-hang-google-sheet', 'Workflow Tự Động Ghi Đơn & Cảnh Báo Tồn Kho', 'Luồng tự động hóa đồng bộ đơn mới về Google Sheets và gửi thông báo Telegram/Zalo trong 1 phút.', 'Mẫu workflow n8n/Make đơn giản cho shop nhỏ không cần phần mềm ERP cồng kềnh. Tự động ghi nhận đơn hàng mới vào Google Sheets, tính doanh thu ngày và nhắn tin cảnh báo khi sản phẩm sắp hết hàng.', 'workflow', 'Đa ngành', 690000, NULL, '/images/cat-workflow.webp', 'original', 'Template workflow JSON do nhóm tự xây dựng, kèm hướng dẫn thiết lập từng bước.', '{"target_shop_size":"1-5 người","platforms":["Google Sheets","Telegram","Webhook"],"deliverables":["File JSON workflow nhập 1 chạm vào n8n/Make","Mẫu Google Sheets quản lý đơn hàng, doanh thu ngày & tồn kho","Tài liệu nối Webhook và cài đặt cảnh báo hết hàng qua Telegram"],"tech_stack":["n8n / Make","Google Sheets","Telegram Bot"],"setup_time_minutes":45,"guide_summary":"Import file JSON vào n8n/Make, chọn Google Sheets mẫu và dán Bot Token Telegram để chạy tự động.","preview_highlights":["File JSON workflow n8n/Make tự động ghi nhận đơn mới từ Webhook về Google Sheets.","Bảng tính mẫu tự động tính doanh thu theo ngày và trừ tồn kho theo mã SKU.","Gửi thông báo ngay về Telegram khi có đơn mới hoặc mặt hàng sắp chạm ngưỡng hết kho."],"case_studies":[{"shop_name":"Kho Phụ Kiện Bàn Làm Việc","shop_type":"Shop đồ công nghệ nhỏ (3 người, Hà Nội)","rating":5,"quote":"Trước đây cuối ngày mới cộng sổ đơn nên hay bị bán lố mấy mã ít hàng. Từ khi gắn cảnh báo Telegram khi tồn kho dưới 5 cái, không còn bị báo hết hàng cho khách sau khi đã chốt.","outcome":"Loại bỏ hoàn toàn lỗi hết hàng đột xuất và tiết kiệm 1 giờ tổng kết sổ mỗi tối"},{"shop_name":"Tiệm Nến Thơm Mùa Hè","shop_type":"Xưởng thủ công nhỏ (2 người, Đà Nẵng)","rating":4.9,"quote":"Không cần mua phần mềm bán hàng hàng tháng, chỉ dùng Google Sheets miễn phí kết hợp workflow này là theo dõi đủ doanh thu và nguyên liệu.","outcome":"Vận hành tự động trên Google Sheets với chi phí duy trì 0 đồng mỗi tháng"}]}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
