INSERT INTO public.scenarios (
  id, code, title, prompt_text, industry, budget_vnd, difficulty, expected_product_id, acceptable_product_ids, rubric_note, sort_order, is_active
) VALUES (
  '6c4b5a6b-7c8d-4901-b234-def123456789'::uuid, 'SC-04', 'Kịch bản 4: Shop đa kênh giờ cao điểm cần tự động ghi đơn & chốt inbox', 'Bạn vận hành shop bán đa kênh trên Shopee, TikTok Shop và Facebook (1–3 người), ngân sách tối đa 700.000đ. Trong giờ cao điểm hay bị sót đơn và chậm trả lời tin nhắn, bạn cần luồng tự động ghi đơn mới về Google Sheets kèm báo Telegram hoặc bộ kịch bản trả lời inbox chốt đơn nhanh.', 'Đa ngành', 700000, 'medium', '6a9e55b6-44d7-40b1-cf54-5b6c7d8e9f01'::uuid, ARRAY['5f8d44a5-33c6-4fa0-be43-4a5b6c7d8e9f'::uuid]::uuid[], 'Đáp án chuẩn là Workflow Tự Động Ghi Đơn & Cảnh Báo Tồn Kho (690.000đ) để xử lý triệt để chống sót đơn qua Google Sheets & Telegram; chấp nhận Prompt Pack Chăm Sóc Khách & Chốt Đơn Đa Kênh (250.000đ) nếu người tham gia ưu tiên giải quyết nhanh khâu trả lời inbox.', 4, true
) ON CONFLICT (id) DO UPDATE SET
  code = EXCLUDED.code,
